28	
29	/** The claims people on a sheet make. */
30	@Service
31	public class ClaimService {
32	
33	    /** Written for a due that has no rate to work from. */
34	    private static final String NO_RATE = "n/a";
35	
36	    /** The name a claim's period number takes when its date falls in no period. */
37	    private static final String NO_PERIOD = "X";
38	
39	    private final ClaimRepository claims;
40	    private final ClaimLogRepository logs;
41	    private final PersonRepository people;
42	    private final RateService rates;
43	    private final PersonGradeService grades;
44	    private final SheetService sheets;
45	    private final PeriodRepository periods;
46	    private final SettingService settings;
47	    private final Audit audit;
48	
49	    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RateService rates,
50	            PersonGradeService grades, SheetService sheets, PeriodRepository periods, SettingService settings, Audit audit) {
51	        this.periods = periods;
52	        this.settings = settings;
53	        this.claims = claims;
54	        this.logs = logs;
55	        this.people = people;
56	        this.rates = rates;
57	        this.grades = grades;
58	        this.sheets = sheets;
59	        this.audit = audit;
60	    }
61	
62	    /** The sheet's claims, newest first. */
63	    public List<Claim> list(String sheetId) {
64	        return claims.findBySheetIdOrderByListedDesc(sheetId);
65	    }
66	
67	    /** Add a claim for a person; a missing date takes the sheet's today. Its due-by is fixed now: its
68	     *  date plus the terms in force on that date for the person's grade then. A negative amount is a
69	     *  correction and must name a SETTLED claim of the person it corrects. */
70	    @Transactional
71	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
72	            String corrects) {
73	        Person person = person(sheetId, personId);
74	        corrects = numberOf(corrects);
75	        LocalDate on = date != null ? date : sheets.today(sheetId);
76	        refuseClosed(sheetId, on);
77	        refuseRetired(person, on);
78	        refuseBadCorrection(sheetId, personId, amount, corrects);
79	        LocalDate dueBy = on.plusDays(settings.termsFor(sheetId, grades.gradeOn(personId, on), on));
80	        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), on, dueBy, noteOf(note),
81	                corrects));
82	        log(sheetId, user, person, added);
83	        record("CLAIM_ADDED", sheetId, user, person, added);
84	        return added;
85	    }
86	
87	    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today. Any
88	     *  other claim is refused: an OPEN one is changed by voiding it and adding a new one. */
89	    @Transactional
90	    public Claim update(String sheetId, String user, Long personId, Long id, BigDecimal amount, LocalDate date,
91	            String note, String corrects) {
92	        Person person = person(sheetId, personId);
93	        corrects = numberOf(corrects);
94	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
95	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
96	        if (claim.getStatus() != ClaimStatus.DRAFT) {
97	            throw new ClaimNotEditableException(claim.getStatus());
98	        }
99	        LocalDate on = date != null ? date : sheets.today(sheetId);
100	        refuseClosed(sheetId, claim.getDate());
101	        refuseClosed(sheetId, on);
102	        refuseRetired(person, on);
103	        refuseBadCorrection(sheetId, personId, amount, corrects);
104	        claim.setAmount(scaled(amount));
105	        claim.setCorrects(corrects);
106	        claim.setDate(on);
107	        claim.setNote(noteOf(note));
108	        Claim saved = claims.saveAndFlush(claim);
109	        record("CLAIM_EDITED", sheetId, user, person, saved);
110	        return saved;
111	    }
112	
113	    /** Move a claim to a new status; a change its status does not allow, or one the sheet's
114	     *  permission matrix does not let the user's role make, is refused, as is the user who opened a
115	     *  claim settling it. A clerk settling a claim whose due is above the clerk limit
116	     *  leaves it PENDING a steward's approval instead. */
117	    @Transactional
118	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
119	        Person person = person(sheetId, personId);
120	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
121	        // read below is its latest state.
122	        if (to == ClaimStatus.OPEN) {
123	            sheets.lock(sheetId);
124	        }
125	        Claim claim = claim(sheetId, personId, id);
126	        settings.refuseUnless(sheetId, user, switch (to) {
127	            case OPEN -> Permission.OPEN;
128	            case SETTLED -> Permission.SETTLE;
129	            case VOID -> Permission.VOID;
130	            case DRAFT, PENDING -> throw new StatusChangeRefusedException(claim.getStatus(), to);
131	        });
132	        refuseClosed(sheetId, claim.getDate());
133	        if (!claim.getStatus().canMoveTo(to)) {
134	            throw new StatusChangeRefusedException(claim.getStatus(), to);
135	        }
136	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
137	            throw new OwnClaimSettleRefusedException(user);
138	        }
139	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
140	            throw new StatusChangeRefusedException(claim.getStatus(), to);
141	        }
142	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
143	        // gathered by then.
144	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
145	        if (to == ClaimStatus.SETTLED) {
146	            refuseUnproved(sheetId, claim, due);
147	        }
148	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
149	            to = ClaimStatus.PENDING;
150	        }
151	        claim.setStatus(to);
152	        if (to == ClaimStatus.OPEN) {
153	            claim.setNumber(nextNumber(sheetId, claim.getDate()));
154	            claim.setOpenedBy(user);
155	        } else if (to == ClaimStatus.SETTLED) {
156	            claim.setSettledDue(due);
157	        }
158	        Claim saved = claims.saveAndFlush(claim);
159	        log(sheetId, user, person, saved);
160	        String event = switch (to) {
161	            case OPEN -> "CLAIM_OPENED";
162	            case PENDING -> "CLAIM_PENDING";
163	            case SETTLED -> "CLAIM_SETTLED";
164	            case VOID -> "CLAIM_VOIDED";
165	            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
166	        };
167	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
168	        if (to == ClaimStatus.SETTLED) {
169	            line += " due=" + settledDueText(saved);
170	        }
171	        audit.recordOnCommit(line);
172	        return saved;
173	    }
174	
175	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
176	     *  the claim counts in no total, is not overdue, cannot be settled and no statement binds it. A
177	     *  claim that is not OPEN, a date not after today, or a claim dated in a closed period, is refused. */
178	    @Transactional
179	    public Claim defer(String sheetId, String user, Long personId, Long id, LocalDate until) {
180	        Person person = person(sheetId, personId);
181	        Claim claim = claim(sheetId, personId, id);
182	        refuseClosed(sheetId, claim.getDate());
183	        if (claim.getStatus() != ClaimStatus.OPEN) {
184	            throw new DeferRefusedException("A " + claim.getStatus() + " claim cannot be deferred");
185	        }
186	        if (!until.isAfter(sheets.today(sheetId))) {
187	            throw new DeferRefusedException("A claim is deferred to a date after the sheet's today");
188	        }
189	        claim.setDeferredUntil(until);
190	        Claim saved = claims.saveAndFlush(claim);
191	        audit.recordOnCommit(line("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber())
192	                + " until=" + until);
193	        return saved;
194	    }
195	
196	    /** A steward approves a PENDING claim: it is SETTLED, its due frozen at this moment. Anyone else,
197	     *  the user who opened it, or a claim that is not PENDING, is refused. */
198	    @Transactional
199	    public Claim approve(String sheetId, String user, Long personId, Long id) {
200	        Person person = person(sheetId, personId);
201	        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.SETTLED);
202	        if (user.equals(claim.getOpenedBy())) {
203	            throw new OwnClaimSettleRefusedException(user);
204	        }
205	        BigDecimal due = dueOf(sheetId, person, claim);
206	        refuseUnproved(sheetId, claim, due);
207	        claim.setSettledDue(due);
208	        claim.setStatus(ClaimStatus.SETTLED);
209	        Claim saved = claims.saveAndFlush(claim);
210	        log(sheetId, user, person, saved);
211	        audit.recordOnCommit(line("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber())
212	                + " due=" + settledDueText(saved));
213	        return saved;
214	    }
215	
216	    /** Add a proof to a claim: its proofs count rises by one. A SETTLED or VOID claim, or one dated in
217	     *  a closed period, is refused. */
218	    @Transactional
219	    public Claim addProof(String sheetId, String user, Long personId, Long id) {
220	        Person person = person(sheetId, personId);
221	        Claim claim = claim(sheetId, personId, id);
222	        refuseClosed(sheetId, claim.getDate());
223	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
224	            throw new ProofRefusedException(claim.getStatus());
225	        }
226	        claim.addProof();
227	        Claim saved = claims.saveAndFlush(claim);
228	        audit.recordOnCommit(line("CLAIM_PROOF_ADDED", sheetId, user, person, saved, saved.getNumber())
229	                + " proofs=" + saved.getProofs());
230	        return saved;
231	    }
232	
233	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by the person's
234	     *  last statement if that statement bound it. Anyone else, or a claim that is not PENDING, is
235	     *  refused. */
236	    @Transactional
237	    public Claim reject(String sheetId, String user, Long personId, Long id, String reason) {
238	        Person person = person(sheetId, personId);
239	        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.OPEN);
240	        claim.setStatus(ClaimStatus.OPEN);
241	        Claim saved = claims.saveAndFlush(claim);
242	        log(sheetId, user, person, saved);
243	        audit.recordOnCommit(line("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber())
244	                + " reason=" + reason.trim());
245	        return saved;
246	    }
247	
248	    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
249	     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
250	     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
251	     *  one dated in a closed period, is refused. */
252	    @Transactional
253	    public Claim resettle(String sheetId, String user, Long personId, Long id) {
254	        Person person = person(sheetId, personId);
255	        Claim claim = claim(sheetId, personId, id);
256	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
257	            throw new ResettleRefusedException(user);
258	        }
259	        if (claim.getStatus() != ClaimStatus.SETTLED) {
260	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
261	        }
262	        refuseClosed(sheetId, claim.getDate());
263	        String old = settledDueText(claim);
264	        BigDecimal figure = liveFigureOf(sheetId, person, claim);
265	        claim.setSettledDue(figure == null ? null : figure.add(lateChargeOf(sheetId, claim, figure, true)));
266	        Claim saved = claims.saveAndFlush(claim);
267	        log(sheetId, user, person, saved);
268	        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
269	                + " old=" + old + " new=" + settledDueText(saved));
270	        return saved;
271	    }
272	
273	    /** A user whose role the sheet's permission matrix lets reassign (by the standing rule a steward)
274	     *  moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
275	     *  number and date, loses any figure a statement bound it to (live again until its new person's
276	     *  next statement), and is listed as its new person's newest claim. Anyone else, a SETTLED or VOID
277	     *  claim, a correction (it names a claim of its own person), a claim dated in a closed period, or
278	     *  a move to the same person or to one retired before the claim's date, is refused. */
279	    @Transactional
280	    public Claim reassign(String sheetId, String user, Long personId, Long id, Long toPersonId) {
281	        Person from = person(sheetId, personId);
282	        Person to = person(sheetId, toPersonId);
283	        Claim claim = claim(sheetId, personId, id);
284	        if (!settings.allows(sheetId, user, Permission.REASSIGN)) {
285	            throw new ReassignRefusedException(user);
286	        }
287	        if (!claim.getStatus().canReassign()) {
288	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
289	        }
290	        if (from.getId().equals(to.getId())) {
291	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
292	        }
293	        if (claim.isCorrection()) {
294	            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
295	        }
296	        refuseClosed(sheetId, claim.getDate());
297	        refuseRetired(to, claim.getDate());
298	        claim.setPersonId(to.getId());
299	        claim.unbind();
300	        claims.saveAndFlush(claim);
301	        claims.relist(claim.getId());
302	        Claim saved = claim(sheetId, to.getId(), id);
303	        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
304	                + " from=" + from.getName() + " to=" + to.getName());
305	        return saved;
306	    }
307	
308	    /** A claim's status log, oldest first: one line per status it has had. */
309	    public List<String> logOf(Long claimId) {
310	        return logs.findByClaimIdOrderByIdAsc(claimId).stream().map(ClaimLogEntry::text).toList();
311	    }
312	
313	    /** The status logs of the sheet's claims by claim id, each oldest first. */
314	    public Map<Long, List<String>> logsOf(String sheetId) {
315	        return logs.findBySheetIdOrderByIdAsc(sheetId).stream().collect(Collectors.groupingBy(
316	                ClaimLogEntry::getClaimId, Collectors.mapping(ClaimLogEntry::text, Collectors.toList())));
317	    }
318	
319	    /** The status each of the sheet's claims had at the end of a day, by claim id, as its status log
320	     *  records it: the last status it moved to on or before that day. A claim added after it has none. */
321	    public Map<Long, ClaimStatus> statusesAsOf(String sheetId, LocalDate day) {
322	        Map<Long, ClaimStatus> statuses = new HashMap<>();
323	        for (ClaimLogEntry entry : logs.findBySheetIdOrderByIdAsc(sheetId)) {
324	            if (!entry.getOn().isAfter(day)) {
325	                statuses.put(entry.getClaimId(), entry.getStatus());
326	            }
327	        }
328	        return statuses;
329	    }
330	
331	    /** Log the status a claim has just moved to (or been added in): by whom, on the sheet's today, and
332	     *  its due as it is now. */
333	    private void log(String sheetId, String user, Person person, Claim claim) {
334	        BigDecimal due = dueOf(sheetId, person, claim);
335	        logs.save(new ClaimLogEntry(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
336	                due != null ? due.toPlainString() : NO_RATE));
337	    }
338	
339	    /** The PENDING claim a steward approves or rejects; refused when it is not PENDING, dated in a
340	     *  closed period, or the user is not a steward. */
341	    private Claim pending(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
342	        Claim claim = claim(sheetId, personId, id);
343	        refuseClosed(sheetId, claim.getDate());
344	        if (claim.getStatus() != ClaimStatus.PENDING) {
345	            throw new StatusChangeRefusedException(claim.getStatus(), to);
346	        }
347	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
348	            throw new ApprovalRefusedException(user);
349	        }
350	        return claim;
351	    }
352	
353	    private Claim claim(String sheetId, Long personId, Long id) {
354	        return claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
355	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
356	    }
357	
358	    private static String settledDueText(Claim claim) {
359	        return claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : NO_RATE;
360	    }
361	
362	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
363	     *  after it) the next within the period its date falls in, <period>-<n>, or X-<n> when it falls
364	     *  in none; otherwise the sheet's next sheet-wide number. Taken with the sheet locked. */
365	    private String nextNumber(String sheetId, LocalDate date) {
366	        LocalDate from = settings.periodNumberingFrom(sheetId);
367	        if (from == null || sheets.today(sheetId).isBefore(from)) {
368	            return String.valueOf(sheets.nextClaimNumber(sheetId));
369	        }
370	        String prefix = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
371	                .filter(period -> period.contains(date))
372	                .findFirst().map(Period::getName).orElse(NO_PERIOD) + "-";
373	        long last = claims.numbers(sheetId).stream()
374	                .filter(number -> number.startsWith(prefix))
375	                .map(number -> number.substring(prefix.length()))
376	                .filter(n -> n.matches("\\d{1,18}"))
377	                .mapToLong(Long::parseLong)
378	                .max().orElse(0);
379	        return prefix + (last + 1);
380	    }
381	
382	    /** The figure a claim shows: the due fixed when it was settled, else (unless it is PENDING, which
383	     *  no statement binds) the figure its person's last statement bound it to, else its due at the
384	     *  person's grade rate; null when it has none. */
385	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
386	        if (claim.getSettledDue() != null) {
387	            return claim.getSettledDue();
388	        }
389	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue() : liveFigureOf(sheetId, person, claim);
390	    }
391	
392	    /** The due a claim shows: its figure plus its late charge (none while it is deferred: it is not
393	     *  overdue then); null when it has no figure. */
394	    public BigDecimal dueOf(String sheetId, Person person, Claim claim) {
395	        BigDecimal figure = figureOf(sheetId, person, claim);
396	        boolean open = claim.getStatus().isOpen() && !claim.deferredOn(sheets.today(sheetId));
397	        return figure == null ? null : figure.add(lateChargeOf(sheetId, claim, figure, open));
398	    }
399	
400	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by is
401	     *  before the sheet's today) or a correction, else the late percent of the figure for every 30-day
402	     *  boundary it is overdue past (its due-by plus 30, 60, 90 ... days), the late percent in force on that
403	     *  boundary date of the figure, rounded to two decimals as the claim's date decides (see roundingOf), the
404	     *  charges added up. Never bound by a statement: it follows the
405	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
406	     *  claim as if it were still OPEN. */
407	    private BigDecimal lateChargeOf(String sheetId, Claim claim, BigDecimal figure, boolean open) {
408	        BigDecimal none = BigDecimal.ZERO.setScale(2);
409	        if (!open || claim.isCorrection()) {
410	            return none;
411	        }
412	        long days = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId));
413	        if (days < 30) {
414	            return none;
415	        }
416	        RoundingMode rounding = roundingOf(sheetId, claim);
417	        BigDecimal charge = none;
418	        for (long boundary = 1; boundary <= days / 30; boundary++) {
419	            BigDecimal pct = settings.latePct(sheetId, claim.getDueBy().plusDays(30 * boundary));
420	            if (pct.signum() != 0) {
421	                charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
422	            }
423	        }
424	        return charge;
425	    }
426	
427	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
428	     *  on the claim's date: amount times rate
429	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf), and at least the sheet's floor in force on its date unless it
430	     *  is a correction; null when no rate applies. */
431	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim) {
432	        BigDecimal amount = claim.getAmount();
433	        RoundingMode rounding = roundingOf(sheetId, claim);
434	        return rates.rateOn(sheetId, grades.gradeOn(person.getId(), claim.getDate()), claim.getDate())
435	                .map(Rate::getRate)
436	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
437	                .map(due -> claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate())))
438	                .orElse(null);
439	    }
440	
441	    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
442	     *  it corrects. */
443	    public LocalDate roundsBy(String sheetId, Claim claim) {
444	        if (!claim.isCorrection() || claim.getCorrects() == null) {
445	            return claim.getDate();
446	        }
447	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
448	                .map(Claim::getDate).orElse(claim.getDate());
449	    }
450	
451	    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
452	    private RoundingMode roundingOf(String sheetId, Claim claim) {
453	        return settings.roundingOn(sheetId, roundsBy(sheetId, claim));
454	    }
455	
456	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a due of n/a
457	     *  is within any limit, and a steward settles anything. */
458	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
459	        BigDecimal limit = settings.clerkLimit(sheetId);
460	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
461	            return false;
462	        }
463	        return settings.roleOf(sheetId, user) == Role.CLERK;
464	    }
465	
466	    /** A claim whose due is above the proof threshold in force on its date cannot be settled or
467	     *  approved while it has no proofs; a due of n/a, or no threshold, asks for none. */
468	    private void refuseUnproved(String sheetId, Claim claim, BigDecimal due) {
469	        BigDecimal threshold = settings.proofThreshold(sheetId, claim.getDate());
470	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
471	            throw new ProofRequiredException(due, threshold);
472	        }
473	    }
474	
475	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
476	     *  any other amount names none. */
477	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
478	        if (amount.signum() >= 0) {
479	            if (corrects != null) {
480	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
481	            }
482	            return;
483	        }
484	        if (corrects == null) {
485	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
486	        }
487	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
488	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
489	        if (!settled) {
490	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
491	        }
492	    }
493	
494	    /** A claim dated inside a closed period cannot be added, edited, opened, settled or voided. */
495	    private void refuseClosed(String sheetId, LocalDate date) {
496	        if (periods.closedOn(sheetId, date)) {
497	            throw new PeriodClosedException("A claim dated " + date + " falls in a closed period");
498	        }
499	    }
500	
501	    /** A claim dated after its person's retirement date cannot be added or moved there. */
502	    private static void refuseRetired(Person person, LocalDate date) {
503	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
504	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
505	        }
506	    }
507	
508	    private Person person(String sheetId, Long personId) {
509	        return people.findByIdAndSheetId(personId, sheetId)
510	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
511	    }
512	
513	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
514	        record(event, sheetId, user, person, claim, claim.getNumber());
515	    }
516	
517	    /** One audit line about a claim; a claim with a number carries it at the end. */
518	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
519	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
520	    }
521	
522	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
523	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
524	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
525	                + (number != null ? " number=" + number : "");
526	    }
527	
528	    private static BigDecimal scaled(BigDecimal amount) {
529	        return amount.setScale(2, RoundingMode.UNNECESSARY);
530	    }
531	
532	    /** A claim number as typed: trimmed, null when blank. */
533	    private static String numberOf(String number) {
534	        return number == null || number.isBlank() ? null : number.trim();
535	    }
536	
537	    private static String noteOf(String note) {
538	        return note == null ? "" : note.trim();
539	    }
540	}
