70	/** Whether a claim is a correction: its amount is negative. */
71	export function isCorrection(claim: Claim): boolean {
72	  return cents(claim.amount) < 0;
73	}
74	
75	/** Whether a claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED ones do. */
76	export function counts(claim: Claim): boolean {
77	  return isOpen(claim) || claim.status === 'SETTLED';
78	}
