85	/** An amount in cents, from the two-decimal string the server sends. */
86	export function cents(amount: string): number {
87	  return Math.round(Number(amount) * 100);
88	}
89	
90	/** What a late charge works from: the sheet's late percent (two decimals) in force on a date and its today; and what a claim's figures round by: the sheet's policy date (blank for its today). */
91	export interface Late {
92	  pct: (date: string) => string;
93	  today: string | null;
94	  policyDate: string;
95	}
96	
97	/** Whether a claim's live figures round half up: it rounds by a date before the sheet's policy date
98	 *  (its today when the policy date is blank); otherwise they round half to even. */
99	function roundsHalfUp(claim: Claim, late: Late): boolean {
100	  const policy = late.policyDate !== '' ? late.policyDate : late.today;
101	  return policy !== null && claim.roundsBy < policy;
102	}
103	
104	/** A claim's figure in cents: the due fixed when it was settled; otherwise, unless it is PENDING
105	 *  (no statement binds it then), the figure a statement bound it to; otherwise its amount times the rate in force on its date among its grade's rates,
106	 *  raised to the sheet's floor in force on its date (in cents) unless it is a correction; null when it has no figure. */
107	function figureCents(claim: Claim, rates: Rate[], floor: (date: string) => number, halfUp: boolean): number | null {
108	  if (claim.settledDue !== null) return cents(claim.settledDue);
109	  if (claim.stated && claim.status !== 'PENDING') return claim.statedDue === null ? null : cents(claim.statedDue);
110	  const rate = rateOn(rates, claim.date);
111	  if (rate === null) return null;
112	  const due = dueCents(cents(claim.amount), rate, halfUp);
113	  return isCorrection(claim) ? due : Math.max(due, floor(claim.date));
114	}
115	
116	/** A claim's due in cents: its figure plus its late charge: for every full 30 days an OPEN or PENDING claim is
117	 *  overdue, the late percent in force on that boundary (its due-by plus 30, 60, 90 ... days) of the figure,
118	 *  rounded like a due, the charges added up (a statement never binds the
119	 *  charge; settling freezes it into the settled due; a correction has none); null when it has no
120	 *  figure. */
121	export function claimDueCents(claim: Claim, rates: Rate[], floor: (date: string) => number, late: Late): number | null {
122	  const halfUp = roundsHalfUp(claim, late);
123	  const figure = figureCents(claim, rates, floor, halfUp);
124	  if (figure === null) return null;
125	  const periods = isCorrection(claim) ? 0 : Math.floor(daysOverdue(claim, late) / 30);
126	  let charge = 0;
127	  for (let boundary = 1; boundary <= periods; boundary++) {
128	    const pct = late.pct(plusDays(claim.dueBy, 30 * boundary));
129	    if (cents(pct) !== 0) charge += dueCents(figure, pct, halfUp);
130	  }
131	  return figure + charge;
132	}
133	
134	/** A date (yyyy-mm-dd) some days on. */
135	function plusDays(date: string, days: number): string {
136	  return new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
137	}
138	
139	/** How many days an OPEN or PENDING claim is past its due-by on the sheet's today; 0 when it is not overdue. */
140	function daysOverdue(claim: Claim, late: Late): number {
141	  if (!overdue(claim, late.today) || late.today === null) return 0;
142	  return Math.round((Date.parse(late.today) - Date.parse(claim.dueBy)) / 86_400_000);
143	}
144	
145	/** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by is before the sheet's today. */
146	export function overdue(claim: Claim, today: string | null): boolean {
147	  return isOpen(claim) && today !== null && claim.dueBy < today && !deferred(claim, today);
148	}
